<script setup>
import { computed, onMounted, reactive, ref } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { apiClient } from "../../utils/api";
import { shanghaiDateTimeText } from "../../utils/shanghai-date";
const loading=ref(false), rows=ref([]), plans=ref([]), people=ref([]), members=ref([]), selected=ref(null), createVisible=ref(false), planVisible=ref(false), editingPlanId=ref(null), memberVisible=ref(false), accountVisible=ref(false), pluginTokenStatus=ref({configured:false}), pluginTokenDialog=ref(false), pluginTokenValue=ref("");
const tenantForm=reactive({name:"",slug:"",owner_person_id:null,plan_code:"trial_7d"}), quotaForm=reactive({member_limit:null,shop_limit:null}), memberForm=reactive({person_id:null,role:"member"}), accountForm=reactive({name:"",username:"",password:"",roles:["operator"]});
const planForm=reactive({name:"",duration_days:30,subscription_status:"active",account_limit:1,shop_limit:2,unlimited_accounts:false,unlimited_shops:false}), statusLabels={active:"已开通",trial:"体验中",expired:"已到期",suspended:"已暂停"};
const title=computed(()=>selected.value?.name||"企业详情");
const activePlans=computed(()=>plans.value.filter(plan=>Number(plan.active)));
function planName(code,tenant=null){if(tenant?.slug==="default")return "默认企业（内部空间）";return plans.value.find(item=>item.code===code)?.name||code||"未设置"}
function quotaText(value,unit){return value==null?"不限":`${value} ${unit}`}
function formatDateTime(value){return value?shanghaiDateTimeText(value,{assumeUtcWhenNaive:true}):"长期有效"}
async function load(){loading.value=true;try{const [tenants,users,tenantPlans]=await Promise.all([apiClient.get("/api/tenants"),apiClient.get("/api/people"),apiClient.get("/api/tenants/plans")]);rows.value=tenants;people.value=users||[];plans.value=tenantPlans||[];if(selected.value){selected.value=rows.value.find(row=>row.id===selected.value.id)||null;if(selected.value)await Promise.all([loadMembers(),loadPluginTokenStatus()]);}}catch(error){ElMessage.error(error.message||"企业列表加载失败");}finally{loading.value=false;}}
async function loadMembers(){members.value=await apiClient.get(`/api/tenants/members?tenant_id=${selected.value.id}`)}
async function loadPluginTokenStatus(){pluginTokenStatus.value=await apiClient.get(`/api/tenants/plugin-token?tenant_id=${selected.value.id}`)}
async function open(row){selected.value=row;Object.assign(quotaForm,{member_limit:row.member_limit,shop_limit:row.shop_limit});pluginTokenValue.value="";await Promise.all([loadMembers(),loadPluginTokenStatus()]);}
async function createTenant(){try{await apiClient.post("/api/tenants",tenantForm);ElMessage.success(`企业已创建并按「${planName(tenantForm.plan_code)}」开通`);createVisible.value=false;Object.assign(tenantForm,{name:"",slug:"",owner_person_id:null,plan_code:"trial_7d"});await load();}catch(error){ElMessage.error(error.message||"创建企业失败");}}
async function saveQuotas(){try{await apiClient.post("/api/tenants/quotas",{tenant_id:selected.value.id,...quotaForm});ElMessage.success("套餐额度已保存");await load();}catch(error){ElMessage.error(error.message||"保存套餐额度失败");}}
async function clearQuotas(){quotaForm.member_limit=null;quotaForm.shop_limit=null;await saveQuotas();}
async function plan(code){const target=activePlans.value.find(item=>item.code===code);if(!target)return;try{await ElMessageBox.confirm(`将为「${selected.value.name}」开通「${target.name}」，期限从现在重新计算，并按该套餐覆盖账号/店铺上限。确认继续吗？`,"确认调整套餐",{type:"warning",confirmButtonText:"确认开通"});await apiClient.post("/api/tenants/subscription",{tenant_id:selected.value.id,plan_code:code});ElMessage.success("授权与套餐额度已生效");await load();}catch(error){if(error!=="cancel")ElMessage.error(error.message||"授权失败");}}
function openPlanEditor(row=null){editingPlanId.value=row?.id||null;Object.assign(planForm,row?{name:row.name,duration_days:row.duration_days,subscription_status:row.subscription_status,account_limit:row.account_limit,shop_limit:row.shop_limit,unlimited_accounts:row.account_limit==null,unlimited_shops:row.shop_limit==null}:{name:"",duration_days:30,subscription_status:"active",account_limit:1,shop_limit:2,unlimited_accounts:false,unlimited_shops:false});planVisible.value=true;}
async function savePlan(){const payload={name:planForm.name,duration_days:planForm.duration_days,subscription_status:planForm.subscription_status,account_limit:planForm.unlimited_accounts?null:planForm.account_limit,shop_limit:planForm.unlimited_shops?null:planForm.shop_limit};try{if(editingPlanId.value)await apiClient.put("/api/tenants/plans",{id:editingPlanId.value,...payload});else await apiClient.post("/api/tenants/plans",payload);ElMessage.success(editingPlanId.value?"套餐已更新":"套餐已创建");planVisible.value=false;await load();}catch(error){ElMessage.error(error.message||"保存套餐失败");}}
async function togglePlan(row){try{await apiClient.put("/api/tenants/plans",{id:row.id,name:row.name,duration_days:row.duration_days,subscription_status:row.subscription_status,account_limit:row.account_limit,shop_limit:row.shop_limit,active:Number(row.active)?0:1});ElMessage.success(Number(row.active)?"套餐已停用；历史企业授权不受影响":"套餐已启用");await load();}catch(error){ElMessage.error(error.message||"套餐状态更新失败");}}
async function suspend(){try{await ElMessageBox.confirm(`暂停后「${selected.value.name}」的成员将不能使用业务功能。确认继续吗？`,"暂停企业",{type:"warning",confirmButtonText:"确认暂停"});await apiClient.post("/api/tenants/subscription",{tenant_id:selected.value.id,subscription_status:"suspended"});ElMessage.success("企业已暂停");await load();}catch(error){if(error!=="cancel")ElMessage.error(error.message||"暂停失败");}}
async function saveMember(){try{await apiClient.put("/api/tenants/members",{tenant_id:selected.value.id,...memberForm,active:1});memberVisible.value=false;await loadMembers();await load();}catch(error){ElMessage.error(error.message||"保存成员失败");}}
async function remove(row){try{await ElMessageBox.confirm(`确认移除「${row.name}」吗？账号不会被删除。`,"移除成员",{type:"warning"});await apiClient.put("/api/tenants/members",{tenant_id:selected.value.id,person_id:row.person_id,role:row.role,active:0});await loadMembers();await load();}catch(error){if(error!=="cancel")ElMessage.error(error.message||"移除失败");}}
async function createAccount(){try{const person=await apiClient.post("/api/people",accountForm);memberForm.person_id=person.id||person.person_id;accountVisible.value=false;memberVisible.value=true;Object.assign(accountForm,{name:"",username:"",password:"",roles:["operator"]});await load();ElMessage.success("子账号已创建，请设置企业角色后保存");}catch(error){ElMessage.error(error.message||"创建子账号失败");}}
async function archive(){try{await ElMessageBox.confirm(`将归档「${selected.value.name}」，全部成员会被移出，但不直接删除业务数据。`,`归档企业`,{type:"error"});await apiClient.post("/api/tenants/archive",{tenant_id:selected.value.id});selected.value=null;members.value=[];await load();ElMessage.success("企业已归档");}catch(error){if(error!=="cancel")ElMessage.error(error.message||"归档失败");}}
async function issuePluginToken(){try{if(pluginTokenStatus.value.configured)await ElMessageBox.confirm("生成新令牌会立即撤销旧令牌，已配置旧令牌的插件需要重新粘贴。","重置企业插件令牌",{type:"warning"});const result=await apiClient.post("/api/tenants/plugin-token",{tenant_id:selected.value.id});pluginTokenValue.value=result.token;pluginTokenDialog.value=true;await loadPluginTokenStatus().catch(()=>{});}catch(error){if(error!=="cancel")ElMessage.error(error.message||"生成插件令牌失败");}}
async function revokePluginToken(){try{await ElMessageBox.confirm("撤销后，该企业所有已配置此令牌的浏览器插件将立即无法连接。","撤销企业插件令牌",{type:"warning"});await apiClient.delete(`/api/tenants/plugin-token?tenant_id=${selected.value.id}`);pluginTokenStatus.value={configured:false};ElMessage.success("插件令牌已撤销");}catch(error){if(error!=="cancel")ElMessage.error(error.message||"撤销插件令牌失败");}}
async function copyPluginToken(){try{await navigator.clipboard.writeText(pluginTokenValue.value);ElMessage.success("令牌已复制");}catch(error){ElMessage.error("复制失败，请手动选择并复制令牌");}}
onMounted(load);
</script>
<template>
  <main class="tenant-page" v-loading="loading">
    <header><div><h1>企业管理</h1><p>管理企业、成员账号、订阅权限与归档。</p></div><div><el-button @click="load">刷新</el-button><el-button type="primary" @click="createVisible=true">新增企业</el-button></div></header>
    <section class="plan-catalog">
      <div class="catalog-head"><div><h2>套餐目录</h2><p>套餐账号数包含主账号；编辑套餐只影响后续新开通/重新授权，现有企业额度不会被静默改写。</p></div><el-button type="primary" plain @click="openPlanEditor()">新增套餐</el-button></div>
      <el-table :data="plans" row-key="id">
        <el-table-column label="套餐名称" min-width="170"><template #default="{row}">{{row.name}} <el-tag v-if="Number(row.is_builtin)" size="small" type="info">预置</el-tag></template></el-table-column>
        <el-table-column label="期限" width="110"><template #default="{row}">{{row.duration_days}} 天</template></el-table-column>
        <el-table-column label="套餐类型" width="110"><template #default="{row}">{{row.subscription_status==='trial'?'体验':'正式'}}</template></el-table-column>
        <el-table-column label="账号总数（含主账号）" min-width="180"><template #default="{row}">{{quotaText(row.account_limit,'个')}}</template></el-table-column>
        <el-table-column label="店铺上限" width="120"><template #default="{row}">{{quotaText(row.shop_limit,'个')}}</template></el-table-column>
        <el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="Number(row.active)?'success':'info'">{{Number(row.active)?'可开通':'已停用'}}</el-tag></template></el-table-column>
        <el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openPlanEditor(row)">编辑</el-button><el-button link :type="Number(row.active)?'danger':'success'" @click="togglePlan(row)">{{Number(row.active)?'停用':'启用'}}</el-button></template></el-table-column>
      </el-table>
    </section>
    <section class="workspace">
      <aside><strong>企业列表</strong><button v-for="row in rows" :key="row.id" :class="{active:selected?.id===row.id}" @click="open(row)"><b>{{row.name}}</b><small>{{planName(row.plan_code,row)}} · {{row.member_count}} 人</small></button></aside>
      <section class="detail">
        <el-empty v-if="!selected" description="选择企业后管理成员、授权和归档" />
        <template v-else>
          <div class="detail-head"><div><h2>{{title}}</h2><span>{{selected.slug}} · {{statusLabels[selected.subscription_status]||selected.subscription_status}}</span></div><el-tag :type="selected.access_allowed?'success':'danger'">{{selected.access_allowed?'可使用':'不可使用'}}</el-tag></div>
          <el-descriptions :column="3" border><el-descriptions-item label="套餐">{{planName(selected.plan_code,selected)}}</el-descriptions-item><el-descriptions-item label="到期">{{formatDateTime(selected.subscription_expires_at)}}</el-descriptions-item><el-descriptions-item label="成员">{{selected.member_count}}</el-descriptions-item><el-descriptions-item label="子账号用量">{{selected.sub_account_count}} / {{selected.member_limit == null ? '不限' : selected.member_limit}}</el-descriptions-item><el-descriptions-item label="店铺用量">{{selected.shop_count}} / {{selected.shop_limit == null ? '不限' : selected.shop_limit}}</el-descriptions-item></el-descriptions>
          <section class="block"><h3>成员与子账号</h3><div class="block-actions"><el-button @click="memberVisible=true">加入现有用户</el-button><el-button type="primary" plain @click="accountVisible=true">创建子账号</el-button></div><el-table :data="members"><el-table-column prop="name" label="姓名" /><el-table-column prop="username" label="登录账号" /><el-table-column prop="role" label="企业角色" /><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="danger" :disabled="row.role==='owner'" @click="remove(row)">移除</el-button></template></el-table-column></el-table></section>
          <section class="block"><h3>套餐与授权</h3><p>选择套餐会从当前时间重新计算到期时间，并同步套餐账号与店铺额度。</p><div class="actions"><el-button v-for="item in activePlans" :key="item.id" :type="item.subscription_status==='trial'?'default':'primary'" @click="plan(item.code)">{{item.name}} · {{item.duration_days}} 天</el-button><el-button type="danger" plain @click="suspend">暂停企业</el-button></div></section>
          <section class="block quota-block"><div><h3>套餐资源额度</h3><p>套餐账号总数包含负责人；负责人以外的所有企业账号（包括企业管理员）计入子账号额度。留空表示不限。调低额度不会停用现有账号或店铺，只会阻止新增。</p></div><el-form inline><el-form-item label="子账号上限"><el-input-number v-model="quotaForm.member_limit" :min="0" :max="1000000" :step="1" controls-position="right" /></el-form-item><el-form-item label="店铺上限"><el-input-number v-model="quotaForm.shop_limit" :min="0" :max="1000000" :step="1" controls-position="right" /></el-form-item><el-button type="primary" @click="saveQuotas">保存额度</el-button><el-button @click="clearQuotas">设为不限</el-button></el-form></section>
          <section class="block plugin-access"><div><h3>浏览器插件接入</h3><p>{{pluginTokenStatus.configured?'已配置企业专属令牌；重置会使旧令牌立即失效。':'尚未配置企业专属令牌。'}}</p><small>令牌仅在生成时显示一次，请粘贴到浏览器插件的“ERP 回传密钥”中。</small></div><div class="actions"><el-button type="primary" @click="issuePluginToken">{{pluginTokenStatus.configured?'重置令牌':'生成令牌'}}</el-button><el-button type="danger" plain :disabled="!pluginTokenStatus.configured" @click="revokePluginToken">撤销令牌</el-button></div></section>
          <section class="danger"><div><h3>危险操作</h3><p>归档会停用企业、移除成员，不直接删除业务数据。</p></div><el-button type="danger" @click="archive">归档企业</el-button></section>
        </template>
      </section>
    </section>
    <el-dialog v-model="createVisible" title="新增企业" width="520px"><el-form label-width="110px"><el-form-item label="企业名称"><el-input v-model="tenantForm.name" /></el-form-item><el-form-item label="企业标识"><el-input v-model="tenantForm.slug" placeholder="例如 acme-shop" /></el-form-item><el-form-item label="开通套餐"><el-select v-model="tenantForm.plan_code" style="width:100%"><el-option v-for="item in activePlans" :key="item.code" :value="item.code" :label="`${item.name} · ${item.duration_days} 天 · ${quotaText(item.account_limit,'账号')} · ${quotaText(item.shop_limit,'店铺')}`" /></el-select></el-form-item><el-form-item label="现有负责人"><el-select v-model="tenantForm.owner_person_id" clearable filterable style="width:100%"><el-option v-for="person in people" :key="person.id" :label="`${person.name}（${person.username||'未设账号'}）`" :value="person.id" /></el-select></el-form-item></el-form><p class="quota-hint">创建时会按所选套餐设置期限、账号数和店铺数。未绑定负责人/激活码注册将在后续切片实现。</p><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" @click="createTenant">创建</el-button></template></el-dialog>
    <el-dialog v-model="planVisible" :title="editingPlanId?'编辑套餐':'新增套餐'" width="520px"><el-form label-width="130px"><el-form-item label="套餐名称"><el-input v-model="planForm.name" maxlength="80" /></el-form-item><el-form-item label="有效期"><el-input-number v-model="planForm.duration_days" :min="1" :max="3650" :step="1" controls-position="right"/><span class="unit-hint">天</span></el-form-item><el-form-item label="套餐类型"><el-select v-model="planForm.subscription_status"><el-option label="体验套餐" value="trial"/><el-option label="正式订阅" value="active"/></el-select></el-form-item><el-form-item label="账号总数（含主账号）"><el-checkbox v-model="planForm.unlimited_accounts">不限</el-checkbox><el-input-number v-model="planForm.account_limit" :min="1" :max="1000000" :disabled="planForm.unlimited_accounts" controls-position="right"/></el-form-item><el-form-item label="店铺上限"><el-checkbox v-model="planForm.unlimited_shops">不限</el-checkbox><el-input-number v-model="planForm.shop_limit" :min="0" :max="1000000" :disabled="planForm.unlimited_shops" controls-position="right"/></el-form-item></el-form><template #footer><el-button @click="planVisible=false">取消</el-button><el-button type="primary" @click="savePlan">保存套餐</el-button></template></el-dialog>
    <el-dialog v-model="memberVisible" title="加入企业成员" width="460px"><el-form label-width="90px"><el-form-item label="用户"><el-select v-model="memberForm.person_id" filterable><el-option v-for="person in people" :key="person.id" :label="`${person.name}（${person.username||'未设账号'}）`" :value="person.id" /></el-select></el-form-item><el-form-item label="企业角色"><el-select v-model="memberForm.role"><el-option label="成员" value="member"/><el-option label="企业管理员" value="admin"/><el-option label="负责人" value="owner"/></el-select></el-form-item></el-form><template #footer><el-button @click="memberVisible=false">取消</el-button><el-button type="primary" @click="saveMember">保存</el-button></template></el-dialog>
    <el-dialog v-model="accountVisible" title="创建子账号" width="460px"><el-form label-width="90px"><el-form-item label="姓名"><el-input v-model="accountForm.name"/></el-form-item><el-form-item label="登录账号"><el-input v-model="accountForm.username"/></el-form-item><el-form-item label="初始密码"><el-input v-model="accountForm.password" show-password/></el-form-item></el-form><template #footer><el-button @click="accountVisible=false">取消</el-button><el-button type="primary" @click="createAccount">创建</el-button></template></el-dialog>
    <el-dialog v-model="pluginTokenDialog" title="企业插件令牌（仅显示一次）" width="620px"><p>请立即复制并粘贴到该企业用户的 Ozon 浏览器插件。关闭此窗口后无法再次查看；遗失时需重置令牌。</p><el-input v-model="pluginTokenValue" readonly /><template #footer><el-button @click="pluginTokenDialog=false">关闭</el-button><el-button type="primary" @click="copyPluginToken">复制令牌</el-button></template></el-dialog>
  </main>
</template>
<style scoped>
.tenant-page{padding:24px}.tenant-page header,.catalog-head,.detail-head,.block-actions,.danger{display:flex;justify-content:space-between;gap:12px}.tenant-page h1,.detail h2,.block h3,.danger h3,.catalog-head h2{margin:0}.tenant-page p,.detail-head span,.danger p,.quota-hint{color:#64748b}.plan-catalog{margin:18px 0;padding:18px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.catalog-head{align-items:center;margin-bottom:14px}.catalog-head h2{font-size:18px}.catalog-head p{margin:6px 0 0}.workspace{display:grid;grid-template-columns:260px 1fr;min-height:620px;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden}.workspace aside{display:grid;align-content:start;gap:8px;padding:18px;border-right:1px solid #e5e7eb;background:#f8fafc}.workspace aside button{display:grid;gap:4px;padding:12px;border:0;border-radius:8px;background:transparent;text-align:left;cursor:pointer}.workspace aside button.active{background:#eaf2ff;color:#2563eb}.workspace aside small{color:#64748b}.detail{padding:24px}.detail-head{margin-bottom:18px}.block{margin-top:22px}.block h3{margin-bottom:10px}.block-actions{justify-content:flex-end;margin-bottom:10px}.actions{display:flex;flex-wrap:wrap;gap:10px}.danger{margin-top:24px;padding:16px;border:1px solid #fecaca;border-radius:10px;background:#fff7f7}.plugin-access{align-items:center;padding:16px;border:1px solid #dbeafe;border-radius:10px;background:#f8fbff}.plugin-access p{margin:8px 0}.plugin-access small{color:#64748b}.quota-block p{margin:0 0 14px}.quota-hint{margin:0 0 8px 110px;font-size:12px}.unit-hint{margin-left:8px;color:#64748b}
@media(max-width:760px){.workspace{grid-template-columns:1fr}.workspace aside{border-right:0;border-bottom:1px solid #e5e7eb}.detail{padding:16px}.plugin-access{align-items:flex-start;flex-direction:column}.plan-catalog{padding:12px}.catalog-head{align-items:flex-start;flex-direction:column}}
</style>
